def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的人口問題、金字塔與公共對策資料推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的出生死亡、遷移、年齡結構、分母、尺度與政策對象。", f"整理證據：分開人口問題的現象、原因、群體影響與對策結果；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」同時處理人口資料與政策限制。", "排除誘答：檢查是否只看總人口、單一比例、單一補助或單一都市案例，並找出被忽略的地方條件。", "結論回查：確認年份、行政範圍、分母、政策期間與受影響群體一致；條件改變時重新評估。"]
    return {"id": f"question-social-content-geo-ad-iv-4-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ad-iv-4"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫人口問題與公共對策情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ad-iv-4", "examPatternRefs": refs, "solutionStrategy": "先辨識少子化、老化與遷移的資料證據，再按地方尺度比較政策對象、供給、成本與實際效果。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ad-iv-4-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
